const message = $input.first().json.message;
if (message?.chat?.type !== 'private') return [];

const chatId = message.chat.id;
const text = (message.text ?? '').trim().replace(/^\x60+|\x60+$/g, '').trim();
const action = text.toLowerCase().normalize('NFD').replace(/\p{M}/gu, '').replace(/^[¡!¿?\s]+|[¡!¿?.,\s]+$/g, '');
const respond = reply => [{ json: { chatId, reply } }];
const call = (action, input = {}) => [{ json: { chatId, payload: { action, chatId: String(chatId), ...input } } }];
const link = text.match(/^\/start(?:@\w+)?\s+([A-Za-z0-9_-]{43})$/i);
if (link) return call('link', { code: link[1] });
const welcome = '¡Hola! Soy el asistente de incidencias de Tuxtla Gutiérrez. ¿Qué quieres hacer?\n\n1. Consultar un reporte por folio\n2. Ver mis reportes recientes\n3. Registrar una incidencia\n4. Ver ayuda\n\nToca un botón o responde con el número. Para usar tus reportes, abre Telegram desde tu cuenta ciudadana y pulsa Iniciar.';
const lookupHelp = 'Pega el folio completo del reporte, incluidos los guiones. Si no lo tienes, toca Mis reportes recientes o escribe 2.';
const reportHelp = 'Envía en un solo mensaje la categoría, el título, la descripción, la latitud y la longitud. Separa cada dato con |.\n\nCategorías: bache, alumbrado o basura.\n\nEjemplo:\nbache | Bache en la calle | Está frente al parque | 16.75 | -93.11\n\nUsa punto decimal y coordenadas de Tuxtla Gutiérrez.';
const help = 'Abierta: recibimos tu reporte.\nEn proceso: el equipo está atendiendo la incidencia.\nResuelta: el equipo marcó la incidencia como resuelta.\nCerrada: concluyó el seguimiento.\n\nEscribe menú para volver a las opciones.';
const folioPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (/^\/(?:start|menu)(?:@\w+)?(?:\s+.*)?$/i.test(text) || ['hola', 'buen dia', 'buenos dias', 'buenas', 'buenas tardes', 'buenas noches', 'menu', 'inicio'].includes(action)) return respond(welcome);
if (['4', 'ayuda'].includes(action) || /^\/ayuda(?:@\w+)?$/i.test(text)) return respond(help);
if (['1', 'consultar mi reporte', 'consultar reporte'].includes(action)) return respond(lookupHelp);
if (['2', 'mis reportes recientes', 'mis reportes', '/misreportes'].includes(action)) return call('recent');
if (['3', 'registrar incidencia', 'registrar una incidencia'].includes(action)) return respond(reportHelp);

const status = text.match(/^\/estado(?:@\w+)?(?:\s+([\s\S]+))?$/i);
const folio = (status ? status[1]?.trim() : text) ?? '';
if (folioPattern.test(folio)) return call('status', { folio: folio.toLowerCase() });
if (status || /^[0-9a-f]{8}-/i.test(folio)) return respond(lookupHelp);

const report = text.match(/^\/reportar(?:@\w+)?(?:\s+([\s\S]+))?$/i);
if (!report && !text.includes('|')) {
  return respond('Puedes pegar un folio, responder con el número de una opción o escribir menú para ver qué puedo hacer.');
}
if (report && !report[1]) return respond(reportHelp);
const fields = (report ? report[1] : text).split('|').map(field => field.trim());
if (fields.length !== 5) return respond('Necesito cinco datos separados por |.\n\n' + reportHelp);
const [rawCategory, title, description, lat, lon] = fields;
const category = rawCategory.toLowerCase();
if (!['bache', 'alumbrado', 'basura'].includes(category)) return respond('Elige una categoría válida: bache, alumbrado o basura.\n\n' + reportHelp);
if (!title || title.length > 150) return respond('Escribe un título de entre 1 y 150 caracteres y vuelve a enviar los cinco datos.');
if (!description || description.length > 2000) return respond('Escribe una descripción de entre 1 y 2,000 caracteres y vuelve a enviar los cinco datos.');
const coordinatePattern = /^-?\d+(\.\d+)?$/;
if (!coordinatePattern.test(lat) || !coordinatePattern.test(lon)) return respond('Escribe la latitud y la longitud con punto decimal, como 16.75 | -93.11, y vuelve a enviar los cinco datos.');
return call('create', { incident: { category, title, description, latitude: Number(lat), longitude: Number(lon) } });

const { chatId, payload } = $('Validar mensaje').first().json;
const response = $input.first().json;
const data = response.body?.data;
const labels = { abierta: 'Abierta', en_proceso: 'En proceso', resuelta: 'Resuelta', cerrada: 'Cerrada' };
let reply = 'El servicio de incidencias no está disponible en este momento. Intenta más tarde.';
if (response.statusCode === 200 && data) {
  if (payload.action === 'link') {
    reply = 'Tu cuenta quedó vinculada. ¿Qué quieres hacer?\n\n1. Consultar por folio\n2. Ver mis reportes recientes\n3. Registrar una incidencia\n4. Ver ayuda';
  } else if (payload.action === 'create') {
    reply = 'Incidencia registrada. Guarda este folio para consultar el avance:\n\n' + data.id;
  } else if (payload.action === 'recent') {
    const lines = data.map(item => [String(item.title).slice(0, 150), 'Estado: ' + (labels[item.status] ?? 'Sin información'), 'Folio: ' + item.id].join('\n'));
    reply = lines.length ? ['Tus reportes más recientes', ...lines, 'Pega un folio para ver el detalle.'].join('\n\n') : 'Aún no tienes reportes. Toca Registrar incidencia para crear uno.';
  } else {
    const lines = ['Folio: ' + data.id, 'Estado: ' + (labels[data.status] ?? 'Sin información')];
    const next = {
      abierta: 'Recibimos tu reporte. Está pendiente de atención.',
      en_proceso: 'El equipo está atendiendo la incidencia.',
      resuelta: 'La incidencia fue atendida y está pendiente de cierre.',
      cerrada: 'El seguimiento del reporte concluyó.',
    };
    if (next[data.status]) lines.push(next[data.status]);
    const date = new Date(data.updatedAt ?? data.createdAt ?? '');
    if (Number.isFinite(date.getTime())) {
      lines.push('Última actualización: ' + date.toLocaleString('es-MX', {
        timeZone: 'America/Mexico_City', dateStyle: 'medium', timeStyle: 'short',
      }));
    }
    reply = lines.join('\n');
  }
} else if ([400, 403, 404, 409, 422].includes(response.statusCode)) {
  reply = response.body?.error?.message ?? reply;
} else if (payload.action === 'create') {
  reply = 'No pude confirmar el registro. Consulta Mis reportes recientes antes de reenviarlo.';
}
return [{ json: { chatId, reply } }];
